	if body := strings.TrimSpace(rec.Body.String()); body != "[]" {
		t.Fatalf("body = %q, want []", body)
	}
	if len(fake.listed) != 1 || fake.listed[0] != "" {
		t.Fatalf("List calls = %q, want one unfiltered call", fake.listed)
	}
}

func TestListReturnsCharges(t *testing.T) {
	fake := &fakeCharges{list: []Charge{
		{ID: 1, Amount: 500, Currency: "USD", Status: "CAPTURED"},
		{ID: 2, Amount: 700, Currency: "USD", Status: "CAPTURED"},
	}}
	h := NewHandlers(fake, noReceipts{})
	rec := httptest.NewRecorder()

	h.list(rec, httptest.NewRequest(http.MethodGet, "/charges", nil))

	want := `[{"id":1,"amount":500,"currency":"USD","status":"CAPTURED"},` +
		`{"id":2,"amount":700,"currency":"USD","status":"CAPTURED"}]`
	if body := strings.TrimSpace(rec.Body.String()); body != want {
		t.Fatalf("body = %s, want %s", body, want)
	}
}

func TestListCurrencyIsNormalised(t *testing.T) {
	for _, in := range []string{"usd", "USD", "uSd"} {
		fake := &fakeCharges{}
		h := NewHandlers(fake, noReceipts{})
		rec := httptest.NewRecorder()

		h.list(rec, httptest.NewRequest(http.MethodGet, "/charges?currency="+in, nil))

		if rec.Code != http.StatusOK {
			t.Fatalf("%s: status = %d, want 200", in, rec.Code)
		}
		if len(fake.listed) != 1 || fake.listed[0] != "USD" {
			t.Fatalf("%s: List calls = %q, want [USD]", in, fake.listed)
		}
	}
}

func TestListInvalidCurrencyIsRejectedAndNotQueried(t *testing.T) {
	for _, query := range []string{
		"currency=",
		"currency=us",
		"currency=usdd",
		"currency=us1",
		"currency=u%20d",
		"currency=%C3%A9ur", // é is not A to Z
		"currency=usd&currency=eur",
		"currency=US%00",
	} {
		fake := &fakeCharges{}
		h := NewHandlers(fake, noReceipts{})
		rec := httptest.NewRecorder()

		h.list(rec, httptest.NewRequest(http.MethodGet, "/charges?"+query, nil))

		if rec.Code != http.StatusBadRequest {
			t.Fatalf("%s: status = %d, want 400", query, rec.Code)
		}
		if len(fake.listed) != 0 {
			t.Fatalf("%s: List was called %d time(s)", query, len(fake.listed))
		}
	}
}
